from __future__ import annotations
import argparse,csv,json,random,shutil,uuid
from collections import defaultdict
from datetime import datetime,timedelta,timezone
from pathlib import Path

PROFILES={"tiny":(25,30,2,80),"small":(500,300,5,2500),"medium":(5000,2000,12,25000),"large":(20000,8000,30,100000),"xlarge":(50000,15000,50,250000)}
SCENARIOS={"normal","peak-sale","fraud-attack","inventory-shortage","payment-degradation","returns-spike","marketing-campaign","mixed-chaos"}
REGIONS=["South","North","West","East","Central"]; CATEGORIES=["Laptops","Mobiles","Audio","Accessories","Home","Fashion","Beauty","Sports","Books"]; BRANDS=["Aster","Nova","Vertex","Nimbus","Orion"]

def iso(d): return d.astimezone(timezone.utc).replace(microsecond=0).isoformat().replace("+00:00","Z")
def parse(v):
 d=datetime.fromisoformat(v.replace("Z","+00:00")); return d if d.tzinfo else d.replace(tzinfo=timezone.utc)
def tok(p,n,w=6): return f"{p}-{n:0{w}d}"
def randtime(r,a,b): return a+timedelta(seconds=r.randrange(max(1,int((b-a).total_seconds()))))
def csvout(p,rows):
 rows=list(rows); p.parent.mkdir(parents=True,exist_ok=True)
 if not rows: p.write_text("",encoding="utf-8"); return 0
 with p.open("w",newline="",encoding="utf-8") as f: w=csv.DictWriter(f,fieldnames=list(rows[0])); w.writeheader(); w.writerows(rows)
 return len(rows)
def jsonl(p,rows):
 rows=list(rows); p.parent.mkdir(parents=True,exist_ok=True)
 with p.open("w",encoding="utf-8") as f:
  for x in rows:f.write(json.dumps(x,default=str)+"\n")
 return len(rows)

class Gen:
 def __init__(self,profile,scenario,seed,asof,days,out):
  self.profile=profile; self.scenario=scenario; self.r=random.Random(seed); self.seed=seed; self.asof=asof; self.start=asof-timedelta(days=days); self.days=days; self.out=out; self.x=defaultdict(list); self.ev=0; self.nc,self.np,self.nw,self.no=PROFILES[profile]
 def event(self,svc,typ,eid,at,payload):
  self.ev+=1; return {"event_id":tok("EVT",self.ev,9),"service":svc,"event_type":typ,"entity_id":eid,"occurred_at":iso(at),"trace_id":uuid.uuid4().hex,"payload":payload}
 def run(self): self.master();self.orders();self.behavior();self.ai();self.obs();return self.write()
 def master(self):
  for i,c in enumerate(CATEGORIES,1):self.x["categories"].append({"category_id":tok("CAT",i,3),"name":c,"parent_category_id":"","level":2,"active":True})
  for i in range(1,max(4,self.nw)+1):self.x["sellers"].append({"seller_id":tok("SELLER",i),"seller_name":f"Seller {i}","region":self.r.choice(REGIONS),"rating":round(self.r.uniform(3.5,5),2),"active":True})
  for i in range(1,self.nc+1):
   cid=tok("CUST",i); region=self.r.choice(REGIONS); created=randtime(self.r,self.start-timedelta(days=800),self.asof)
   self.x["customers"].append({"customer_id":cid,"first_name":f"Learner{i}","last_name":"Customer","email":f"learner{i}@example.test","phone":f"+91-90000{i%100000:05d}","region":region,"city":region+" City","created_at":iso(created),"marketing_consent":self.r.random()<.75,"segment":self.r.choice(["NEW","REGULAR","VIP","AT_RISK"]),"account_status":"ACTIVE"})
   self.x["addresses"].append({"address_id":tok("ADDR",i),"customer_id":cid,"type":"HOME","line1":f"{i} Learning Street","city":region+" City","region":region,"postal_code":f"{600000+i%99999:06d}","country":"IN","is_default":True})
   self.x["loyalty_accounts"].append({"customer_id":cid,"tier":self.r.choice(["BRONZE","SILVER","GOLD"]),"points_balance":self.r.randint(0,3000),"lifetime_points":self.r.randint(100,10000)})
   self.x["devices"].append({"device_id":tok("DEV",i),"customer_id":cid,"device_type":self.r.choice(["Android","iOS","Web"]),"trusted":self.r.random()>.08,"first_seen_at":iso(created)})
  for i in range(1,self.np+1):
   pid=tok("P",i); cat=self.r.choice(CATEGORIES); brand=self.r.choice(BRANDS); price=round(self.r.uniform(199,150000),2); seller=self.r.choice(self.x["sellers"])["seller_id"]
   self.x["products"].append({"product_id":pid,"sku":f"SKU-{i:08d}","seller_id":seller,"category_id":tok("CAT",CATEGORIES.index(cat)+1,3),"category":cat,"brand":brand,"name":f"{brand} {cat} {i}","description":f"Synthetic {cat} for learning.","rating":round(self.r.uniform(3,5),2),"review_count":self.r.randint(0,5000),"weight_kg":round(self.r.uniform(.1,10),2),"active":True})
   self.x["prices"].append({"product_id":pid,"currency":"INR","list_price":price,"sale_price":round(price*self.r.uniform(.8,1),2),"cost_price":round(price*.6,2),"effective_from":iso(self.start),"effective_to":""})
  for i in range(1,self.nw+1):self.x["warehouses"].append({"warehouse_id":tok("WH",i,3),"name":f"Warehouse {i}","region":REGIONS[(i-1)%5],"city":f"City{i}","capacity_units":100000,"active":True})
  shortage=.1 if self.scenario in {"inventory-shortage","mixed-chaos"} else 1
  for p in self.x["products"]:
   wh=self.r.choice(self.x["warehouses"]); on=int(self.r.randint(10,300)*shortage);res=min(on,self.r.randint(0,10));self.x["inventory"].append({"warehouse_id":wh["warehouse_id"],"product_id":p["product_id"],"on_hand":on,"reserved":res,"available":on-res,"reorder_point":20,"updated_at":iso(self.asof)})
  for i in range(1,4):self.x["promotions"].append({"promotion_id":tok("PROMO",i,4),"name":f"Promo {i}","discount_type":"PERCENT","discount_value":10,"start_at":iso(self.start),"end_at":iso(self.asof+timedelta(days=30)),"active":True});self.x["coupons"].append({"coupon_code":f"LEARN{i:03d}","promotion_id":tok("PROMO",i,4),"usage_limit":1000,"minimum_cart_value":499})
  for i in range(1,4):self.x["marketing_campaigns"].append({"campaign_id":tok("CMP",i,4),"name":f"Campaign {i}","objective":"CROSS_SELL","channel":"EMAIL","budget":50000,"start_at":iso(self.start),"status":"ACTIVE"})
 def orders(self):
  price={z["product_id"]:z for z in self.x["prices"]}; inv={z["product_id"]:z for z in self.x["inventory"]}; n=int(self.no*(1.8 if self.scenario in {"peak-sale","mixed-chaos"} else 1))
  for i in range(1,n+1):
   oid=tok("ORD",i,8);cart=tok("CART",i,8);c=self.r.choice(self.x["customers"]);at=randtime(self.r,self.start,self.asof);chosen=self.r.sample(self.x["products"],k=min(self.r.choice([1,1,2,3]),self.np));sub=disc=0
   self.x["carts"].append({"cart_id":cart,"customer_id":c["customer_id"],"status":"CONVERTED","channel":"Web","created_at":iso(at-timedelta(minutes=10)),"updated_at":iso(at)})
   for j,p in enumerate(chosen,1):
    q=self.r.choice([1,1,2]);u=float(price[p["product_id"]]["sale_price"]);d=round(u*q*self.r.choice([0,0,.05]),2);line=round(u*q-d,2);sub+=u*q;disc+=d;iid=f"{oid}-I{j}"
    self.x["cart_items"].append({"cart_id":cart,"product_id":p["product_id"],"quantity":q,"unit_price":u});self.x["order_items"].append({"order_item_id":iid,"order_id":oid,"product_id":p["product_id"],"seller_id":p["seller_id"],"quantity":q,"unit_price":u,"discount":d,"line_total":line});self.x["lake_order_events"].append({"event_id":f"{oid}-{iid}","event_type":"order.created","occurred_at":iso(at),"order_id":oid,"customer_id":c["customer_id"],"product_id":p["product_id"],"quantity":q,"unit_price":u,"discount":d,"region":c["region"],"channel":"Web"})
   total=round((sub-disc)*1.18,2); pf=self.r.random()<(.25 if self.scenario in {"payment-degradation","mixed-chaos"} else .035);fraud=self.r.random()<(.15 if self.scenario in {"fraud-attack","mixed-chaos"} else .015);cancel=pf or (fraud and self.r.random()<.5);status="CANCELLED" if cancel else ("DELIVERED" if at<self.asof-timedelta(days=5) else "PAID")
   self.x["orders"].append({"order_id":oid,"customer_id":c["customer_id"],"cart_id":cart,"shipping_address_id":tok("ADDR",int(c["customer_id"].split('-')[-1])),"channel":"Web","currency":"INR","subtotal":round(sub,2),"discount":round(disc,2),"shipping_fee":0,"tax":round((sub-disc)*.18,2),"total":total,"status":status,"fraud_flag":fraud,"created_at":iso(at),"updated_at":iso(at)})
   pid=tok("PAY",i,8);ps="FAILED" if pf else "SUCCEEDED";gw=f"GW-{uuid.uuid4().hex[:12]}";self.x["payment_intents"].append({"payment_id":pid,"order_id":oid,"customer_id":c["customer_id"],"amount":total,"currency":"INR","payment_method":self.r.choice(["UPI","CARD","WALLET"]),"payment_method_ref":f"pm_{uuid.uuid4().hex[:10]}","idempotency_key":f"checkout:{oid}","status":ps,"created_at":iso(at)});self.x["payment_transactions"].append({"transaction_id":tok("TXN",i,9),"payment_id":pid,"order_id":oid,"gateway":"MOCK","gateway_reference":gw,"transaction_type":"AUTH_CAPTURE","amount":total,"status":ps,"latency_ms":self.r.randint(100,6000 if pf else 1200),"created_at":iso(at)});self.x["payment_webhooks"].append({"webhook_id":tok("WHK",i,9),"payment_id":pid,"event_type":"payment.failed" if pf else "payment.succeeded","gateway_reference":gw,"received_at":iso(at),"duplicate":False});self.x["service_events"] += [self.event("payment-service","payment.failed" if pf else "payment.succeeded",pid,at,{"order_id":oid}),self.event("order-service","order.created",oid,at,{"status":status})]
   if not cancel:
    for line in [z for z in self.x["order_items"] if z["order_id"]==oid]:self.x["inventory_reservations"].append({"reservation_id":f"RES-{uuid.uuid4().hex[:8]}","order_id":oid,"product_id":line["product_id"],"warehouse_id":inv[line["product_id"]]["warehouse_id"],"quantity":line["quantity"],"status":"RESERVED","created_at":iso(at)})
    sid=tok("SHIP",i,8);deliv=status=="DELIVERED";self.x["shipments"].append({"shipment_id":sid,"order_id":oid,"carrier":"MockCarrier","tracking_number":f"TRK-{uuid.uuid4().hex[:12]}","status":"DELIVERED" if deliv else "IN_TRANSIT","shipped_at":iso(at),"delivered_at":iso(at+timedelta(days=3)) if deliv else "","estimated_delivery_at":iso(at+timedelta(days=4))});self.x["tracking_events"].append({"tracking_event_id":f"TE-{uuid.uuid4().hex[:8]}","shipment_id":sid,"status":"DELIVERED" if deliv else "IN_TRANSIT","location":c["city"],"occurred_at":iso(min(self.asof,at+timedelta(days=2)))})
    if deliv and self.r.random()<(.35 if self.scenario in {"returns-spike","mixed-chaos"} else .09):
     rid=tok("RET",len(self.x["returns"])+1,8);line=self.r.choice([z for z in self.x["order_items"] if z["order_id"]==oid]);self.x["returns"].append({"return_id":rid,"order_id":oid,"customer_id":c["customer_id"],"reason":"QUALITY","status":"REQUESTED","requested_at":iso(self.asof)});self.x["return_items"].append({"return_id":rid,"order_item_id":line["order_item_id"],"product_id":line["product_id"],"quantity":1,"refund_amount":line["line_total"]});self.x["refunds"].append({"refund_id":tok("RFND",len(self.x["refunds"])+1,8),"payment_id":pid,"order_id":oid,"return_id":rid,"amount":line["line_total"],"status":"SUCCEEDED","created_at":iso(self.asof)})
 def behavior(self):
  for i in range(max(self.no,self.nc*3)):
   c=self.r.choice(self.x["customers"]);p=self.r.choice(self.x["products"]);at=randtime(self.r,self.start,self.asof);a=self.r.choice(["VIEW_PRODUCT","SEARCH","ADD_TO_CART"]);self.x["clickstream_events"].append({"event_id":tok("CLK",i+1,10),"customer_id":c["customer_id"],"session_id":tok("SESSION",i+1,8),"event_type":a,"product_id":p["product_id"] if a!="SEARCH" else "","channel":"Web","occurred_at":iso(at)});self.x["search_events"].append({"search_event_id":tok("SRCH",len(self.x["search_events"])+1,9),"customer_id":c["customer_id"],"session_id":tok("SESSION",i+1,8),"query":p["category"],"result_count":20,"clicked_product_id":p["product_id"],"converted":self.r.random()<.1,"occurred_at":iso(at)}) if a=="SEARCH" else None
  for i in range(min(1000,self.nc)):c=self.r.choice(self.x["customers"]);self.x["marketing_events"].append({"marketing_event_id":tok("MKT",i+1,10),"campaign_id":"CMP-0001","customer_id":c["customer_id"],"channel":"EMAIL","delivered":True,"opened":self.r.random()<.3,"clicked":False,"converted":False,"occurred_at":iso(self.asof)})
  for i in range(min(1000,max(12,self.nc//3))):c=self.r.choice(self.x["customers"]);self.x["support_tickets"].append({"ticket_id":tok("TKT",i+1,8),"customer_id":c["customer_id"],"order_id":"","issue":"Where is my order?","channel":"CHAT","priority":"MEDIUM","status":"OPEN","created_at":iso(self.asof),"resolved_at":""})
 def ai(self):
  returned={z["order_id"] for z in self.x["returns"]};orders={z["order_id"]:z for z in self.x["orders"]}
  for o in self.x["orders"]:self.x["ml_fraud"].append({"order_id":o["order_id"],"amount":o["total"],"item_count":1,"discount_pct":0,"account_age_days":365,"device_trusted":True,"payment_method":"UPI","channel":o["channel"],"is_fraud":o["fraud_flag"]})
  for c in self.x["customers"]:self.x["ml_churn"].append({"customer_id":c["customer_id"],"days_since_last_order":self.r.randint(0,180),"orders_90d":self.r.randint(0,5),"spend_90d":round(self.r.uniform(0,50000),2),"returns_90d":0,"support_tickets_90d":0,"email_engagement":round(self.r.random(),4),"churned":self.r.random()<.15})
  for l in self.x["order_items"]:o=orders[l["order_id"]];self.x["ml_return_risk"].append({"order_item_id":l["order_item_id"],"order_id":l["order_id"],"product_id":l["product_id"],"price":l["unit_price"],"discount_pct":0,"customer_prior_return_rate":round(self.r.random()*.3,4),"delivery_delay_days":0,"product_rating":4,"returned":l["order_id"] in returned});self.x["ml_recommendation_interactions"].append({"customer_id":o["customer_id"],"product_id":l["product_id"],"interaction":"PURCHASE","weight":8,"occurred_at":o["created_at"]});self.x["ml_demand_daily"].append({"product_id":l["product_id"],"date":o["created_at"][:10],"units":l["quantity"],"revenue":l["line_total"]})
  for s in self.x["search_events"]:self.x["ml_search_ranking"].append({"search_event_id":s["search_event_id"],"query":s["query"],"product_id":s["clicked_product_id"],"clicked":1,"converted":int(s["converted"]),"position":1,"semantic_similarity":.8,"popularity_score":.5})
  self.x["ml_review_sentiment"]=[{"review_id":"REV-DEMO","product_id":"P-000001","text":"Synthetic positive review","rating":5,"sentiment_label":"positive"}]
  docs=[{"document_id":"POLICY-RETURNS","title":"Returns Policy","document_type":"policy","text":"Eligible items may be returned within the configured return window.","metadata":{"domain":"returns"}}]+[{"document_id":"PRODUCT-"+p["product_id"],"title":p["name"],"document_type":"product","text":p["name"]+" "+p["description"],"metadata":{"product_id":p["product_id"]}} for p in self.x["products"][:10000]];self.x["rag_documents"]=docs;self.x["vector_corpus"]=[{"chunk_id":d["document_id"]+"-C1","document_id":d["document_id"],"text":d["text"],"text_hash":uuid.uuid5(uuid.NAMESPACE_URL,d["text"]).hex[:16],"metadata":d["metadata"]} for d in docs];self.x["agent_test_cases"]=[{"case_id":"AGENT-001","question":"Where is my order?","expected_tools":["order_lookup","shipment_lookup"],"requires_human":False}];self.x["agent_traces"]=[{"trace_id":uuid.uuid4().hex,"case_id":"AGENT-001","step":1,"node":"tool_call","tool":"order_lookup","status":"SUCCESS","latency_ms":50}]
 def obs(self):
  for i,e in enumerate(self.x["service_events"],1):self.x["service_logs"].append({"timestamp":e["occurred_at"],"level":"ERROR" if "failed" in e["event_type"] else "INFO","service":e["service"],"trace_id":e["trace_id"],"event_type":e["event_type"],"entity_id":e["entity_id"],"message":"Synthetic event"});self.x["service_traces"].append({"trace_id":e["trace_id"],"span_id":f"{i:016x}","service":e["service"],"operation":e["event_type"],"status_code":500 if "failed" in e["event_type"] else 200,"duration_ms":self.r.randint(10,800),"started_at":e["occurred_at"]})
  for s in ["order-service","payment-service","ai-service","mcp-service"]:self.x["service_metrics"].append({"timestamp":iso(self.asof),"service":s,"environment":"learning","requests_total":1000,"error_rate":.01,"p50_ms":50,"p95_ms":300,"p99_ms":700,"cpu_pct":30,"memory_pct":40})
 def write(self):
  cm={"categories":"master/categories.csv","sellers":"master/sellers.csv","customers":"identity/customers.csv","addresses":"identity/addresses.csv","loyalty_accounts":"identity/loyalty_accounts.csv","devices":"identity/devices.csv","products":"catalog/products.csv","prices":"pricing/prices.csv","promotions":"promotions/promotions.csv","coupons":"promotions/coupons.csv","warehouses":"inventory/warehouses.csv","inventory":"inventory/inventory.csv","inventory_reservations":"inventory/reservations.csv","carts":"cart/carts.csv","cart_items":"cart/cart_items.csv","orders":"orders/orders.csv","order_items":"orders/order_items.csv","payment_intents":"payments/payment_intents.csv","payment_transactions":"payments/payment_transactions.csv","refunds":"payments/refunds.csv","shipments":"shipping/shipments.csv","tracking_events":"shipping/tracking_events.csv","returns":"returns/returns.csv","return_items":"returns/return_items.csv","reviews":"reviews/reviews.csv","marketing_campaigns":"marketing/campaigns.csv","marketing_events":"marketing/marketing_events.csv","support_tickets":"support/support_tickets.csv","search_events":"search/search_events.csv","ml_fraud":"ml/fraud_training.csv","ml_churn":"ml/churn_training.csv","ml_return_risk":"ml/return_risk_training.csv","ml_recommendation_interactions":"ml/recommendation_interactions.csv","ml_demand_daily":"ml/demand_daily.csv","ml_review_sentiment":"ml/review_sentiment.csv","ml_search_ranking":"ml/search_ranking.csv","service_metrics":"observability/service_metrics.csv","service_traces":"observability/service_traces.csv"};jm={"payment_webhooks":"payments/payment_webhooks.jsonl","clickstream_events":"events/clickstream_events.jsonl","service_events":"events/service_events.jsonl","lake_order_events":"data-platform/order_events.jsonl","rag_documents":"ai/rag_documents.jsonl","vector_corpus":"ai/vector_corpus.jsonl","agent_test_cases":"ai/agent_test_cases.jsonl","agent_traces":"ai/agent_traces.jsonl","service_logs":"observability/service_logs.jsonl"};counts={k:csvout(self.out/v,self.x[k]) for k,v in cm.items()};counts.update({k:jsonl(self.out/v,self.x[k]) for k,v in jm.items()});self.out.mkdir(parents=True,exist_ok=True);(self.out/"manifest.json").write_text(json.dumps({"generator":"AI Commerce Mock Data Generator","version":"1.1.0","profile":self.profile,"scenario":self.scenario,"seed":self.seed,"record_counts":counts},indent=2),encoding="utf-8");(self.out/"dataset_stats.json").write_text(json.dumps({"customers":len(self.x["customers"]),"products":len(self.x["products"]),"orders":len(self.x["orders"]),"returns":len(self.x["returns"])},indent=2),encoding="utf-8");return counts

def main():
 p=argparse.ArgumentParser();p.add_argument("--profile",choices=PROFILES,default="tiny");p.add_argument("--scenario",choices=sorted(SCENARIOS),default="normal");p.add_argument("--seed",type=int,default=42);p.add_argument("--days",type=int,default=180);p.add_argument("--as-of",default=datetime.now(timezone.utc).isoformat());p.add_argument("--output",default="output/latest");p.add_argument("--reset",action="store_true");p.add_argument("--sync-data-platform",action="store_true");a=p.parse_args();root=Path(__file__).resolve().parent;out=Path(a.output);out=out if out.is_absolute() else root/out
 if a.reset and out.exists():shutil.rmtree(out)
 counts=Gen(a.profile,a.scenario,a.seed,parse(a.as_of),a.days,out).run()
 if a.sync_data_platform:
  t=root.parent/"data-platform"/"sample"/"order_events.jsonl";t.parent.mkdir(parents=True,exist_ok=True);shutil.copy2(out/"data-platform"/"order_events.jsonl",t)
 print("AI COMMERCE MOCK DATA GENERATED",a.profile,a.scenario,"->",out);[print(f"{k:36s} {counts[k]:>10,}") for k in sorted(counts)]
